//! ✅️ Name policies scan original Unicode text and apply only the authored collection uniqueness rule.
use super::*;
use crate::{owned::OwnedRowValidation,row::RowOutcome};
pub struct TextValidation<S:TextRowPath>{input:Option<RetainedCloneBinding>,key:Option<RetainedCloneBinding>,original:Option<RetainedCloneBinding>,names:Option<Box<NameLookup<S>>>,offset:usize,phase:u8,result:Option<Option<RowOutcome>>,closing:bool}
impl<S:TextRowPath> TextValidation<S>{pub fn new()->Self{Self{input:None,key:None,original:None,names:None,offset:0,phase:0,result:None,closing:false}}fn end(&self,text:&str,body:usize)->usize{let mut end=self.offset+(body.saturating_sub(2*size_of::<usize>()+3)/2).min(text.len().saturating_sub(self.offset));while end>self.offset&&!text.is_char_boundary(end){end-=1;}end}}
impl<S:TextRowPath> TextValidation<S>{
 pub fn demand_original(&self,input:RetainedCloneRef<'_,String>,key:RetainedCloneRef<'_,u32>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.result.is_some(){return Err(invalid());}input.check_binding(&self.input)?;key.check_binding(&self.key)?;original.check_binding(&self.original)?;match self.phase{0=>nested(scalar(input.binding_copy_bytes()),1),1=>nested(scalar(key.binding_copy_bytes()),1),2=>nested(scalar(original.binding_copy_bytes()),1),3=>Ok(scalar(2*size_of::<usize>()+3+2*(self.end(input.get(),body)-self.offset))),4=>Ok(birth::<NameLookup<S>>()),5=>nested(self.names.as_ref().ok_or_else(invalid)?.demand(input,key,original,body.saturating_sub(1))?,1),6=>cursor_demand(&self.names,body),_=>Err(invalid())}}
 pub fn advance_original(&mut self,input:RetainedCloneRef<'_,String>,key:RetainedCloneRef<'_,u32>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand_original(input,key,original,body)?;if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=receipt(d);match self.phase{0=>{p=add(input.bind(&mut self.input,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=1;},1=>{p=add(key.bind(&mut self.key,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=2;},2=>{p=add(original.bind(&mut self.original,child(g,1))?.ok_or_else(invalid)?,1)?;self.phase=3;},3=>{let end=self.end(input.get(),body);if input.get()[self.offset..end].chars().any(|c|!c.is_whitespace()){if S::UNIQUE{self.phase=4;}else{self.result=Some(None);}}else if end==input.get().len(){self.result=Some(Some(RowOutcome::Invalid));}self.offset=end;},4=>{self.names=Some(Box::new(NameLookup::new()));self.phase=5;},5=>{let names=self.names.as_mut().ok_or_else(invalid)?;p=add(names.advance(input,key,original,body.saturating_sub(1),child(g,1)).map_err(|e|tag(e,1))?.progress(),1)?;if names.result().is_some(){names.begin_close();self.phase=6;}},6=>{let duplicate=self.names.as_ref().ok_or_else(invalid)?.result().ok_or_else(invalid)?;p=close_cursor(&mut self.names,g)?;if self.names.is_none(){self.result=Some(duplicate.then_some(RowOutcome::Duplicate));}},_=>return Err(invalid())}Ok(if self.result.is_some(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn result(&self)->Option<Option<RowOutcome>>{self.result}
 pub fn begin_close(&mut self){self.closing=true;if let Some(c)=self.names.as_mut(){c.begin_close();}}
}
impl<S:TextRowPath> CursorClose for TextValidation<S>{fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid());}if self.names.is_some(){return cursor_demand(&self.names,body);}RetainedCloneBinding::close_demand(if self.input.is_some(){&self.input}else if self.key.is_some(){&self.key}else{&self.original},body)}fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_mutation_demand_fits(d,g){return Ok(RetainedCloneStep::Progress(Default::default()));}if self.names.is_some(){return close_cursor(&mut self.names,g).map(RetainedCloneStep::Progress);}let s=RetainedCloneBinding::close_one(if self.input.is_some(){&mut self.input}else if self.key.is_some(){&mut self.key}else{&mut self.original},g)?;Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(s.progress())}else{RetainedCloneStep::Progress(s.progress())})}fn terminal_is_empty(&self)->bool{self.closing&&self.names.is_none()&&self.input.is_none()&&self.key.is_none()&&self.original.is_none()}}
impl<S:TextRowPath> Drop for TextValidation<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original text validation retains authored source or name cursor");}}

impl<S:TextRowPath> OwnedRowValidation<String,S::Row> for TextValidation<S>{
 fn demand(&self,input:RetainedCloneRef<'_,String>,key:RetainedCloneRef<'_,u32>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,_:RetainedCloneRef<'_,S::Row>,body:usize)->Result<RetirementDemand,ValueError>{self.demand_original(input,key,original,body)}
 fn advance(&mut self,input:RetainedCloneRef<'_,String>,key:RetainedCloneRef<'_,u32>,original:RetainedCloneRef<'_,EnergyModelSnapshot>,_:RetainedCloneRef<'_,S::Row>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{self.advance_original(input,key,original,body,g)}
 fn result(&self)->Option<Option<RowOutcome>>{Self::result(self)}
 fn begin_close(&mut self){Self::begin_close(self)}
}
